package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"image"
	"image/jpeg"
	"image/png"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

const (
	maxUploadSize = 10 << 20 // 10MB
	tempBaseDir   = "/tmp/imgproc"
	outputDir     = "/var/www/processed"
)

type ProcessingPipeline struct {
	mu       sync.Mutex
	workers  int
	jobQueue chan *ProcessingJob
}

type ProcessingJob struct {
	sourceFile string
	outputFile string
	format     string
	userID     string
}

func NewPipeline(workers int) *ProcessingPipeline {
	p := &ProcessingPipeline{
		workers:  workers,
		jobQueue: make(chan *ProcessingJob, 100),
	}
	for i := 0; i < workers; i++ {
		go p.worker()
	}
	return p
}

func (p *ProcessingPipeline) worker() {
	for job := range p.jobQueue {
		if err := p.processImage(job); err != nil {
			fmt.Printf("Error processing job: %v\n", err)
		}
	}
}

func (p *ProcessingPipeline) processImage(job *ProcessingJob) error {
	srcFile, err := os.Open(job.sourceFile)
	if err != nil {
		return fmt.Errorf("opening source: %w", err)
	}
	defer srcFile.Close()

	img, _, err := image.Decode(srcFile)
	if err != nil {
		return fmt.Errorf("decoding image: %w", err)
	}

	// Create intermediate temp file for processing stages
	intermediatePath := p.createIntermediatePath(job)
	intermediateFile, err := os.Create(intermediatePath)
	if err != nil {
		return fmt.Errorf("creating intermediate: %w", err)
	}

	// Write intermediate result
	switch job.format {
	case "png":
		err = png.Encode(intermediateFile, img)
	case "jpeg", "jpg":
		err = jpeg.Encode(intermediateFile, img, &jpeg.Options{Quality: 85})
	default:
		err = png.Encode(intermediateFile, img)
	}
	intermediateFile.Close()
	if err != nil {
		os.Remove(intermediatePath)
		return fmt.Errorf("encoding intermediate: %w", err)
	}

	// Move to final output
	if err := os.Rename(intermediatePath, job.outputFile); err != nil {
		os.Remove(intermediatePath)
		return fmt.Errorf("moving to output: %w", err)
	}

	// Cleanup source
	os.Remove(job.sourceFile)
	return nil
}

func (p *ProcessingPipeline) createIntermediatePath(job *ProcessingJob) string {
	// Generate path using user-scoped subdirectory
	userDir := filepath.Join(tempBaseDir, "stage", job.userID)
	os.MkdirAll(userDir, 0755)
	return filepath.Join(userDir, generateToken(8)+"."+job.format)
}

func generateToken(length int) string {
	b := make([]byte, length)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func secureFilename(original string) string {
	ext := strings.ToLower(filepath.Ext(original))
	allowed := map[string]bool{".png": true, ".jpg": true, ".jpeg": true}
	if !allowed[ext] {
		ext = ".png"
	}
	return generateToken(16) + ext
}

func (p *ProcessingPipeline) HandleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxUploadSize)

	file, header, err := r.FormFile("image")
	if err != nil {
		http.Error(w, "Invalid upload", http.StatusBadRequest)
		return
	}
	defer file.Close()

	userID := r.Header.Get("X-User-ID")
	if userID == "" || len(userID) > 64 {
		http.Error(w, "Invalid user", http.StatusUnauthorized)
		return
	}

	// Validate content type by reading magic bytes
	buf := make([]byte, 512)
	n, err := file.Read(buf)
	if err != nil && err != io.EOF {
		http.Error(w, "Read error", http.StatusInternalServerError)
		return
	}
	contentType := http.DetectContentType(buf[:n])
	if contentType != "image/png" && contentType != "image/jpeg" {
		http.Error(w, "Unsupported image type", http.StatusBadRequest)
		return
	}
	file.Seek(0, io.SeekStart)

	// Save upload to temp location
	safeName := secureFilename(header.Filename)
	uploadDir := filepath.Join(tempBaseDir, "uploads", userID)
	os.MkdirAll(uploadDir, 0700)
	uploadPath := filepath.Join(uploadDir, safeName)

	dst, err := os.OpenFile(uploadPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		http.Error(w, "Storage error", http.StatusInternalServerError)
		return
	}

	if _, err := io.Copy(dst, file); err != nil {
		dst.Close()
		os.Remove(uploadPath)
		http.Error(w, "Write error", http.StatusInternalServerError)
		return
	}
	dst.Close()

	format := strings.TrimPrefix(filepath.Ext(safeName), ".")
	outputName := generateToken(16) + "." + format

	job := &ProcessingJob{
		sourceFile: uploadPath,
		outputFile: filepath.Join(outputDir, outputName),
		format:     format,
		userID:     userID,
	}

	p.jobQueue <- job

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"status":"queued","output":"%s"}`, outputName)
}

func main() {
	os.MkdirAll(tempBaseDir, 0700)
	os.MkdirAll(outputDir, 0755)

	pipeline := NewPipeline(4)

	http.HandleFunc("/upload", pipeline.HandleUpload)
	fmt.Println("Image processing server starting on :8080")
	http.ListenAndServe(":8080", nil)
}
